"""Evaluate claims against condition-matched evidence records."""

import json


def _canonical_json(value):
    """Return a deterministic JSON representation for exact JSON comparisons."""
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    )


def _superseded_ids(record):
    supersedes = record.get("supersedes", [])
    if isinstance(supersedes, str):
        return {supersedes}
    if isinstance(supersedes, (list, tuple, set)):
        return set(supersedes)
    return set()


def evaluate(request, evidence, policy):
    """Return the support status for one request without modifying inputs."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and not record.get("verified", False):
            continue
        record_conditions = record.get("conditions", {})
        if any(
            name not in record_conditions
            or _canonical_json(record_conditions[name])
            != _canonical_json(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    retained = []
    for index, record in enumerate(eligible):
        source = record.get("source")
        is_superseded = any(
            index != other_index and source in _superseded_ids(other)
            for other_index, other in enumerate(eligible)
        )
        if not is_superseded:
            retained.append(record)

    if not retained:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted({record["source"] for record in retained})
    canonical_values = {_canonical_json(record.get("value")) for record in retained}
    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = retained[0].get("value")
    status = "unsupported" if value is False else "supported"
    return {
        "status": status,
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

